  function alGrid(){const items=alItems();if(state.alVariant==='loading')return '<div class="al-empty" role="status">正在加载…</div>';if(!items.length)return '<div class="al-empty"><i data-lucide="images"></i><span>暂无附件</span></div>';return `<div class="al-grid">${items.map((a,i)=>btn('al-open:'+i,`${a.bad?icon('image-off'):`<img src="${a.src}" alt="${esc(a.name)}">`}<small>${a.dimensions?`<span>${a.dimensions}</span>`:''}<span>${a.size}</span></small>`,'预览 '+a.name,'',`data-al-index="${i}" aria-pressed="${state.rModal==='attachment-library-item'&&state.alItem===i}"`)).join('')}</div>`;}
  function alLibrary(){const total=alItems(0).length+alItems(1).length;return `<div class="al-shell"><div class="al-header">${btn('back',icon('chevron-left'),'返回','bc-icon')}<div><h2>${state.alVariant==='archive'?'导入预览':'导出预览'}</h2><p class="al-subtitle">共 ${total} 张图片</p></div></div>${total?`<div class="al-tabs" role="tablist">${[0,1].map(g=>btn('al-group:'+g,`${g?'自定义图标':'账单附件'} (${alItems(g).length})`,g?'自定义图标':'账单附件','',`role="tab" aria-selected="${state.alGroup===g}" aria-pressed="${state.alGroup===g}"`)).join('')}</div>`:''}<div class="al-scroll" data-al-swipe>${alGrid()}</div></div>`;}
