  function alDialog(){const a=alItems()[state.alItem];return `<div class="al-viewer"><header>${btn('r-close',icon('x'),'关闭','bc-icon')}<span>1 / 1</span><span></span></header><div class="al-stage" data-al-zoom>${a.bad?icon('image-off'):`<img src="${a.src}" alt="${esc(a.name)}" draggable="false">`}</div><footer><div>${esc(a.name)}</div>${a.dimensions?`<span>${a.dimensions}</span>`:''}<span>${a.size}</span></footer></div>`;}
  rSpecs['attachment-library-item']={title:'附件预览',host:'flow-attachment-library',kind:'dialog'};
  const alPreviousModal=rModalBody;rModalBody=function(key){return key==='attachment-library-item'?alDialog():alPreviousModal(key);};
  const alPreviousBuild=rBuildModal;rBuildModal=function(){alPreviousBuild();if(state.rModal==='attachment-library-item'){const layer=phone.querySelector('.bc-sheet-layer');layer.classList.add('al-preview-layer');layer.querySelector('.bc-sheet-title')?.remove();}};
  const alPicker=document.createElement('optgroup');alPicker.label='附件预览 · 原有分组与状态';for(const[key,title]of alVariants.slice(1))alPicker.appendChild(new Option(title,'flow-'+key));picker.appendChild(alPicker);
  root.addEventListener('click',event=>{const el=event.target.closest('[data-action]');if(!el?.dataset.action.startsWith('al-'))return;event.preventDefault();event.stopImmediatePropagation();const[action,value]=el.dataset.action.split(':');if(action==='al-group'){state.alGroup=Number(value);render();}else if(action==='al-open'){state.alItem=Number(value);alScale=1;render();rOpenModal('attachment-library-item');}} ,true);
  let alSwipe;const alPointers=new Map();let alDistance=0,alScale=1;
  root.addEventListener('pointerdown',event=>{if(event.target.closest('[data-al-swipe]'))alSwipe={x:event.clientX,y:event.clientY};if(event.target.closest('[data-al-zoom]')){alPointers.set(event.pointerId,{x:event.clientX,y:event.clientY});if(alPointers.size===2){const p=[...alPointers.values()];alDistance=Math.hypot(p[0].x-p[1].x,p[0].y-p[1].y);}}});
  root.addEventListener('pointermove',event=>{if(!alPointers.has(event.pointerId))return;alPointers.set(event.pointerId,{x:event.clientX,y:event.clientY});if(alPointers.size===2){const p=[...alPointers.values()],scale=Math.max(.5,Math.min(2.5,Math.hypot(p[0].x-p[1].x,p[0].y-p[1].y)/alDistance));const image=phone.querySelector('[data-al-zoom] img');if(image)image.style.transform=`scale(${scale})`;}});
  root.addEventListener('pointerup',event=>{alPointers.delete(event.pointerId);if(!alSwipe)return;const start=alSwipe;alSwipe=null;const dx=event.clientX-start.x,dy=event.clientY-start.y;if(Math.abs(dx)>50&&Math.abs(dx)>Math.abs(dy)){state.alGroup=dx<0?1:0;render();}});
