  root.addEventListener('wheel',event=>{const stage=event.target.closest('[data-al-zoom]');if(!stage)return;event.preventDefault();alScale=Math.max(.5,Math.min(2.5,alScale-event.deltaY*.003));const image=stage.querySelector('img');if(image)image.style.transform=`scale(${alScale})`;},{passive:false});
